style.css:
/* Fixed Auth0 Forms classes and our own component IDs. */
.af-form { background: transparent; color: #dad8cf; }
.af-componentId-account_terms_title h1 { margin: 0 0 20px; color: #f1ece2; font: 600 24px/1.25 -apple-system, BlinkMacSystemFont, sans-serif; }
.af-componentId-rillora_legal_accepted { background: transparent; color: #b8bab2; }
.af-componentId-rillora_legal_accepted p { margin: 0; padding: 0; }
.af-componentId-rillora_legal_accepted label { background: transparent; color: #b8bab2; font-size: 14px; line-height: 1.55; }
.af-componentId-rillora_legal_accepted input[type=checkbox] { width: 18px; height: 18px; margin-top: 2px; accent-color: #bfd79a; }
.af-componentId-rillora_legal_accepted a { display: inline; min-height: 0; padding: 0; color: #dad8cf; font-size: inherit; line-height: inherit; text-decoration: underline; text-underline-offset: 2px; }
.af-button { display: flex; align-items: center; justify-content: center; width: 100%; min-height: 48px; margin-top: 24px; border: 0; border-radius: 10px; background: #cb704c; color: #171c1c; font: 600 16px/1.4 -apple-system, BlinkMacSystemFont, sans-serif; text-align: center; }
.af-button:focus-visible, input:focus-visible, a:focus-visible { outline: 2px solid #bfd79a; outline-offset: 3px; }
